using CheckoutPricing.Application.Checkout;

namespace CheckoutPricing.UnitTests.Application;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithHundredSubtotalPaysNinetyFive()
    {
        var request = new CalculatePayableTotalRequest(CustomerTier.Gold, 100.00m);

        var response = new CalculatePayableTotalHandler().Handle(request);

        Assert.Equal(95.00m, response.PayableTotal);
    }
}

